using System.Windows;
using Tune.Generic.DialogGenerics;
using Tune.Helpers;
using Tune.Models.Music;
using Tune.Models.Playlist;
using Tune.Values.Config;
using Tune.Values.Static;

// Initially generated by AI, but edited.
namespace Tune.Components.UI
{
    public partial class CreatePlaylist : DialogBaseStringPlaylistBase
    {
        

        // ==== Internal Properties ====
        private PlaylistBase? CreatedPlaylist { get; set; }

        // ==== Implement Interfaces ====
        public override PlaylistBase? Result
        {
            get => CreatedPlaylist;
            set => CreatedPlaylist = value;
        }

        private string? _argument;

        public override string? Argument
        {
            get => _argument;
            set
            {
                _argument = value;
                if (!string.IsNullOrEmpty(value))
                    DescriptionTextBlock.Text = value;
            }
        }

        // ==== Constructor ====
        public CreatePlaylist()
        {
            InitializeComponent();
            this.DataContext = this;
            this.Height = 220;
            this.Width = 800;

            ConfirmButton.Click += OnConfirmClick;
            CancelButton.Click += OnCancelClick;
        }

        // ==== UI Logic ====
        private void OnConfirmClick(object sender, RoutedEventArgs e)
        {
            if (string.IsNullOrWhiteSpace(NameInputBox.Text))
                return;

            // Create here
            CreatedPlaylist = new CollectionPlaylist(Guid.NewGuid().ToString(Security.UUID_GEN_MODE), NameInputBox.Text.Trim(), "");
            var service = LoadableServicesHelper.GetPlaylistService();
            if (service == null || !service.IsLoaded)
            {
                // TODO SHOW_TOAST
                MessageBox.Show("Not loaded service or service not exists! Unable to create playlist", Strings.APPLICATION_NAME, MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            var result = service.SavePlaylist(CreatedPlaylist);
            if (!result.Success)
            {
                // TODO SHOW_TOAST
                MessageBox.Show($"Failed to create this playlist: {result.ErrorMessage}", Strings.APPLICATION_NAME, MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            RaiseConfirm();
        }

        private void OnCancelClick(object sender, RoutedEventArgs e)
        {
            CreatedPlaylist = null;
            RaiseCancel();
        }

        private void OnImportFolderClick(object sender, RoutedEventArgs e)
        {
            // TODO: Dir
        }
    }
}